def countdown(n):
    while n > 0:
        yield n
        n -= 1

for i in countdown(3):
    print(i)
print(sum(x * x for x in range(4)))

def shout(func):
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs).upper()
    return wrapper

@shout
def greet(name):
    return "hello " + name

print(greet("ada"))

from functools import wraps

def logged(func):
    @wraps(func)
    def wrapper(*args):
        print("calling", func.__name__)
        return func(*args)
    return wrapper

@logged
def add(a, b):
    return a + b

print(add(2, 3))

