def divide(a, b):
    try:
        result = a / b
    except ZeroDivisionError:
        return "cannot divide by zero"
    else:
        return result
    finally:
        print("done")

print(divide(6, 3))
print(divide(1, 0))

class LowBalance(Exception):
    pass

def withdraw(balance, amount):
    if amount > balance:
        raise LowBalance(f"need {amount - balance} more")
    return balance - amount

try:
    withdraw(10, 25)
except LowBalance as err:
    print("Error:", err)

from contextlib import contextmanager

@contextmanager
def section(name):
    print("start", name)
    try:
        yield
    finally:
        print("end", name)

with section("demo"):
    print("working")

