def numbers():
    n = 1
    while True:
        yield n
        n += 1

def squares(source):
    for n in source:
        yield n * n

def limit(source, count):
    for _ in range(count):
        yield next(source)

print(list(limit(squares(numbers()), 6)))

from functools import wraps

def logged(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        result = func(*args, **kwargs)
        print(f"{func.__name__}{args} -> {result}")
        return result
    return wrapper

@logged
def add(a, b):
    return a + b

add(2, 3)
add(10, 5)

def parse(text):
    try:
        value = int(text)
    except ValueError:
        print(text, "is not a number")
    else:
        print(text, "doubled is", value * 2)
    finally:
        print("checked", text)

parse("21")
parse("abc")

class Vehicle:
    def __init__(self, name):
        self.name = name

    def describe(self):
        return f"{self.name} is a vehicle"

class Bike(Vehicle):
    def __init__(self, name, gears):
        super().__init__(name)
        self.gears = gears

    def describe(self):
        return super().describe() + f" with {self.gears} gears"

print(Bike("Roadster", 21).describe())

from dataclasses import dataclass, field

@dataclass
class Cart:
    owner: str
    items: list = field(default_factory=list)

    def total(self):
        return sum(price for _, price in self.items)

cart = Cart("Ada")
cart.items.append(("pen", 2.5))
cart.items.append(("book", 12.0))
print(cart)
print(cart.total())

